<?php require_once __DIR__."/../config/auth.php";require_role(["admin","warehouse"]);$pdo=db();if($_SERVER["REQUEST_METHOD"]==="POST"){try{check_csrf($_POST["csrf"]??"");$id=(int)$_POST["product"]; $q=abs((float)$_POST["qty"]);$type=$_POST["type"];if($q<=0)throw new Exception("Invalid quantity");$pdo->beginTransaction();$s=$pdo->prepare("SELECT stock_qty FROM products WHERE id=? FOR UPDATE");$s->execute([$id]);$p=$s->fetch();if(!$p)throw new Exception("Product not found");if($type==="out"&&$p["stock_qty"]<$q)throw new Exception("Not enough stock");$delta=$type==="out"?-$q:$q;$pdo->prepare("UPDATE products SET stock_qty=stock_qty+? WHERE id=?")->execute([$delta,$id]);$pdo->prepare("INSERT INTO stock_movements(product_id,user_id,type,qty,note) VALUES(?,?,?,?,?)")->execute([$id,user()["id"],$type,$q,$_POST["note"]]);$pdo->commit();$_SESSION["flash"]=["type"=>"ok","msg"=>"Stock updated."];}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$_SESSION["flash"]=["type"=>"bad","msg"=>$e->getMessage()];}redirect("stock.php");}$ps=$pdo->query("SELECT id,name_en,stock_qty FROM products WHERE is_active=1 ORDER BY name_en")->fetchAll();include __DIR__."/partials/header.php";?><header><h1><?=t("حركة المخزن","Stock")?></h1></header><div class="card"><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><select name="product"><?php foreach($ps as $p):?><option value="<?=$p["id"]?>"><?=e($p["name_en"])?></option><?php endforeach;?></select><select name="type"><option value="in">Stock In</option><option value="out">Stock Out</option></select><input name="qty" type="number" step=".001" placeholder="Qty"><input name="note" placeholder="Note"><button class="btn primary">Update</button></form></div><?php include __DIR__."/partials/footer.php";?>